message.content:
{
  "morphology_wrong_forms": [
    {
      "wrong_form": "空洞する",
      "explanation": "空洞 is a noun (or no-adjective), not a suru-verb root. To make it a verb, it requires the suffix 化する (koudouka suru)."
    },
    {
      "wrong_form": "空洞た",
      "explanation": "As a noun, 空洞 cannot take verbal past tense endings directly without a copula like だ or である."
    },
    {
      "wrong_form": "空洞く",
      "explanation": "Treats the noun as an u-verb, which is grammatically impossible."
    }
  ],
  "collocation_distractors": [
    {
      "collocate": "流暢な空洞",
      "explanation": "流暢 (fluent) is used for language or speech, not physical cavities."
    },
    {
      "collocate": "美味しい空洞",
      "explanation": "美味しい (delicious) applies to food and taste, incompatible with an empty space or cavity."
    },
    {
      "collocate": "迅速な空洞",
      "explanation": "迅速 (rapid/prompt) describes actions or processes, not static geological or structural voids."
    }
  ],
  "collocation_wrong_collocate": {
    "collocate": "密度の空洞",
    "explanation": "密度 (density) contradicts 空洞 (cavity/hollow), as a cavity implies a lack of density."
  },
  "cloze_distractors": [
    {
      "option": "空白",
      "reason": "Means a blank space or whitespace in text, not a physical hollow or cavity."
    },
    {
      "option": "空腹",
      "reason": "Means hunger or an empty stomach, referring to a biological sensation rather than a physical void."
    },
    {
      "option": "虚無",
      "reason": "Means nihilism or nothingness in an abstract/philosophical sense, not a concrete hollow structure."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼のスピーチには内容がなく、完全に空洞だった。",
      "reason": "Incorrect usage: 空洞 refers to physical cavities or hollow spaces, whereas abstract emptiness in speech should use 虚偽 or 中身がない."
    },
    {
      "sentence": "忙しい一日が終わって、心に空洞ができた。",
      "reason": "Incorrect usage: While emotional emptiness is common, the standard idiom is 心に穴があく or 虚無感, not a physical 空洞."
    },
    {
      "sentence": "道路の表面に大きな空洞が走っている。",
      "reason": "Incorrect usage: Underground cavities can form, but roads don't 'run' with a cavity; 裂け目 (crack) or 陥没 (cave-in) is appropriate."
    }
  ],
  "spot_incorrect": {
    "sentence": "歯医者に行って、虫歯できた空洞を埋めてもらった。",
    "planted_error": "できた",
    "error_description": "The particle usage is awkward; it should connect the relative clause smoothly using a possessive or descriptive particle like 'による' or simply modify '空洞' directly as '虫歯でできた空洞'.",
    "corrected version": "歯医者に行って、虫歯でできた空洞を埋めてもらった。"
  },
  "word_family_fake_forms": [
    {
      "fake_form": "空洞性",
      "explanation": "Plausible-sounding derivative noun using 性, but standard Japanese uses 空洞化 (hollowing out)."
    },
    {
      "fake_form": "空洞める",
      "explanation": "Invents a transitive verb form directly from the noun, which does not exist."
    },
    {
      "fake_form": "空洞的",
      "explanation": "Attempts to turn the noun into a na-adjective using 的, which is not standard usage."
    }
  ],
  "particle_candidates": [
    "を",
    "に",
    "で",
    "が"
  ]
}
